<script setup lang="ts">import {exercises} from '~/data/expanded';const current=ref(0);const selected=ref('');const checked=ref(false);const item=computed(()=>exercises[current.value%exercises.length]);const choose=(o:string)=>{selected.value=o;checked.value=true};const next=()=>{current.value++;selected.value='';checked.value=false}</script>
<template><section><div class="page-title"><span class="eyebrow">PRÁTICA</span><h1>Exercícios variados</h1><p class="muted">Feedback imediato e explicações curtas.</p></div><div class="card" style="max-width:700px"><span class="eyebrow">QUESTÃO {{current+1}}</span><h2>{{item.question}}</h2><div class="grid" style="grid-template-columns:1fr 1fr"><button v-for="o in item.options" :key="o" class="button" :style="checked&&o===item.answer?'background:#dff3ee;color:#087f78':''" @click="choose(o)">{{o}}</button></div><div v-if="checked" style="margin-top:22px"><b>{{selected===item.answer?'✓ Correto':'✗ Ainda não'}}</b><p class="muted">{{item.explanation}}</p><button class="button primary" @click="next">Próxima questão</button></div></div></section></template>
